-- 📚 꼭집 주거 사전 — 동·호 지정·배정 방식 · 매입 중심 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 4.4초 · 결과:
-- {"anns": 57, "by_std": {"SH 고유": 2, "공공임대(6·10·50년)": 1, "국민임대": 5, "매입임대": 40, "행복주택": 7, "행복주택(신혼희망)": 2}, "추첨배정": 15, "추첨배정_ex": ["SH_310653", "SH_310650", "2015122300020873"], "희망호수": 2, "희망호수_ex": ["SH_311349", "SH_311087"], "고득점순": 2, "고득점순_ex": ["SH_311349", "SH_311087"], "순번순": 2, "순번순_ex": ["2015122300020850", "2015122300020453"], "선착순": 3, "선착순_ex": ["2015122300020780", "2015122300020682", "2015122300020453"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where cls='동호 지정·배정'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='동호 지정·배정' group by 1)q),'추첨배정',(select count(distinct announcement_id) from y where cls='동호 지정·배정' and t~'(전산\s*추첨|무작위\s*추첨|컴퓨터\s*추첨|추첨[^.]{0,20}(동\s*·?\s*호|배정))'),'추첨배정_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='동호 지정·배정' and t~'(전산\s*추첨|무작위\s*추첨|컴퓨터\s*추첨|추첨[^.]{0,20}(동\s*·?\s*호|배정))' order by 1 desc limit 3)q),'희망호수',(select count(distinct announcement_id) from y where cls='동호 지정·배정' and t~'희망\s*(호수|동\s*·?\s*호|주택)'),'희망호수_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='동호 지정·배정' and t~'희망\s*(호수|동\s*·?\s*호|주택)' order by 1 desc limit 3)q),'고득점순',(select count(distinct announcement_id) from y where cls='동호 지정·배정' and t~'(고득점|점수가\s*높은)'),'고득점순_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='동호 지정·배정' and t~'(고득점|점수가\s*높은)' order by 1 desc limit 3)q),'순번순',(select count(distinct announcement_id) from y where cls='동호 지정·배정' and t~'(순번|예비\s*순번)[^.]{0,30}(대로|순서|순으로)'),'순번순_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='동호 지정·배정' and t~'(순번|예비\s*순번)[^.]{0,30}(대로|순서|순으로)' order by 1 desc limit 3)q),'선착순',(select count(distinct announcement_id) from y where cls='동호 지정·배정' and t~'선착순'),'선착순_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='동호 지정·배정' and t~'선착순' order by 1 desc limit 3)q))j;
